public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // ascending phase
        Character curChar = map.firstKey();
        sb.append(curChar);
        decrement(map, curChar);
        Character last = curChar;
        while (true) {
            Character next = map.higherKey(last);
            if (next == null) break;
            sb.append(next);
            decrement(map, next);
            last = next;
        }
        if (map.isEmpty()) break;
        // descending phase
        curChar = map.lastKey();
        sb.append(curChar);
        decrement(map, curChar);
        last = curChar;
        while (true) {
            Character next = map.lowerKey(last);
            if (next == null) break;
            sb.append(next);
            decrement(map, next);
            last = next;
        }
    }
    return sb.toString();
}
private void decrement(java.util.TreeMap<Character, Integer> map, Character key) {
    int cnt = map.get(key);
    if (cnt == 1) map.remove(key);
    else map.put(key, cnt - 1);
}

