            result.add(curr.intValue());
            for (int i = 0; i <= 9; i++) {
                long next = curr * 10 + i;
                if (next > n) {
                    // No need to explore deeper if next already exceeds n
                    break;
                }
                accept(next);
            }
        }
    };

    // Start DFS for each first digit from 1 to 9
    for (long i = 1; i <= 9 && i <= n; i++) {
        dfs.accept(i);
    }

    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int count = 0; count < n; count++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

